    public function ambilnotriase()
    {
        $kode_header = $this->createantrianumum('A');
        $now = Carbon::now();

        // $id_detail = $this->createLayanandetail();
        $header = ts_antrian_igd::create([
            'no_antri' => $kode_header,
            'created_at' => $now,
            'tgl' => $now,
            'isNoAntrian' => '1'


        ]);
    }
    public function kpo()
    {
