        $unit = auth()->user()->unit;

        $menu = 'kpo';
        return view(
            'dokter.kpo',
            [
                'title' => 'SiRAMAH DOKTER',
                'menu' => $menu,
                'user' => $user,
                'unit' => $unit

            ]
        );
    }
    public function triase()
    {
        $user = auth()->user()->nama;
        $unit = auth()->user()->unit;

        $menu = 'triase';
        $now = Carbon::now()->format('Y-m-d');

        $antrian = DB::select('SELECT no_antri, kode_kunjungan, tgl, no_rm, nama_px, status, status_triase FROM tp_karcis_igd WHERE DATE(tgl) BETWEEN ? AND ?', [$now, $now]);
        $nama = DB::select('SELECT  no_rm, kode_kunjungan FROM ts_kunjungan
        WHERE DATE(tgl_masuk) BETWEEN ? AND ?', [$now, $now]);
        return view(
            'dokter.triase',
            [
                'title' => 'TRIASE DOKTER',
                'menu' => $menu,
                'antrian' => $antrian,
                'nama' => $nama,
                'unit' => $unit,
                'user' => $user
            ]
        );
    }

    public function carinotriase(Request $request)
    {
        $tgl = $request->tgl_kunjungan;
        $antrian = DB::select('SELECT no_antri, tgl, no_rm, nama_px, status, status_triase FROM tp_karcis_igd
      WHERE DATE(tgl) BETWEEN ? AND ?', [$tgl, $tgl]);


        return view(
            'dokter.tabletriase',
            [
                'title' => 'TRIASE DOKTER',
                'antrian' => $antrian
            ]
        );
    }

