                    FROM erm_cppt_kebidanan
                    WHERE STATUS NOT IN (2,3)
                    GROUP BY kode_kunjungan
                ) d2 
                ON d1.kode_kunjungan = d2.kode_kunjungan 
                AND d1.id = d2.max_id
            ) d ON d.kode_kunjungan = a.kode_kunjungan

            -- FIX DOKTER (INI KUNCI)
