    public function ermdokter(Request $request)
    {
        $norm = $request->norm;
        $namapx = $request->namapx;
        $jk = $request->jk;
        $kj = $request->kj;
        $kp = $request->kp;
        $kp = $request->kp;
        $ku = $request->ku;
        $counter = $request->counter;

        $kelas = $request->kelas;
        $tglmasuk = $request->tglmasuk;
        $unit =  $request->unit;


        $ttv = DB::select('SELECT tekanan_darah, keadaan_umum, kesadaran, frekuensi_nafas, frekuensi_nadi, suhu, berat_badan, umur, GCS, spo2 FROM erm_cppt_perawat WHERE no_rm = ? AND kode_kunjungan = ?', [$norm, $kj]);
        $ttvb = DB::select('SELECT tekanan_darah, keadaan_umum, kesadaran, frekuensi_nafas, frekuensi_nadi, suhu, berat_badan, umur, GCS, SPO2 FROM erm_cppt_kebidanan WHERE no_rm = ? AND kode_kunjungan = ?', [$norm, $kj]);
        $ttvc = DB::select('SELECT tekanan_darah, frekuensi_nafas, frekuensi_nadi, suhu, berat_badan, umur, keadaan_umum, kesadaran, gcs, spo2 FROM erm_cppt_kebidanan_bayi WHERE no_rm = ? AND kode_kunjungan = ?', [$norm, $kj]);

        $cek = DB::select('SELECT
      fc_nama_unit1(kode_unit) AS nama_unit
      ,a.*

      FROM assesmen_dokters a
      WHERE  id_pasien = ?', [$norm]);
        $cek1 = DB::select('SELECT a.no_rm, b.kode_layanan_header FROM ts_kunjungan a INNER JOIN ts_layanan_header b
        ON b.kode_kunjungan = a.kode_kunjungan
        WHERE b.kode_unit = ? AND  a.no_rm = ? ', ['3002', $norm]);
        $cekr = DB::select('select *,date(tgl_baca) as tanggalnya,fc_acc_number_ris(id_detail) as acc_number from ts_hasil_expertisi where no_rm = ?', [$norm]);
        $cekpa = DB::select('SELECT
        kode_header
        , id_header
        , id_detail
        , unit_asal
        , no_rm
        , kode_kunjungan
        , fc_nama_px(no_rm) AS nama_px
        , hasil
        , fc_NAMA_PARAMEDIS1(kode_dokter) AS nama_dokter
        , tipe
        , diagnostik_klinik
        , diagnostik_pasca_bedah
        , tgl_baca
         FROM ts_hasil_expertisi_pa WHERE no_rm = ?', [$norm]);

        //    if (count($cek1) == 0) {
        //        echo "<h4 class='text-danger'> Tidak Ada Hasil Laboratorium ...</h5>";
        //    } else {
        //     //    return view('dokter.hasillab', compact(
        //     //        ['cek']
        //     //    ));
        //    }

        return view(
            'dokter.ermdokterview',
            [
                'title' => 'ERM DOKTER',
                'cek' => $cek,
                'cekpa' => $cekpa,

                'cek1' => $cek1,
                'cekr' => $cekr,
                'norm' => $norm,
                'namapx' => $namapx,
                'jk' => $jk,
                'kj' => $kj,
                'tglmasuk' => $tglmasuk,
                'ttv' => $ttv,
                'ttvb' => $ttvb,
                'ttvc' => $ttvc,

                'kelas' => $kelas,
                'kp' => $kp,
                'ku' => $ku,
                'counter' => $counter,
                'unit' => $unit

            ]
        );
    }
    public function icare(Request $request)
    {
        $norm = $request->norm;
        $kp = auth()->user()->kode_paramedis;

        $kpm = DB::select('SELECT kode_dokter_jkn FROM mt_paramedis WHERE kode_paramedis = ?', [$kp]);
        $nobpjs = DB::select('SELECT no_Bpjs FROM mt_pasien WHERE no_rm =?', [$norm]);


        return view(
            'dokter.icare',
            [
                'norm' => $norm,
                'kpm' => $kpm,
                'nobpjs' => $nobpjs,

            ]
        );
    }
    public function riwayatcppt(Request $request)
    {
        $norm = $request->norm;
        $cek = DB::select('SELECT
