    public function formermdokter(Request $request)
    {
        $kj = $request->kj;
        $norm = $request->norm;
        $kelas = $request->kelas;
        $kp = $request->kp;
        $ku = $request->ku;
        $counter = $request->counter;
        $unit = $request->unit;
        // dd($unit);

        $nama = auth()->user()->nama;
        $kgp = auth()->user()->kode_paramedis;



        $now = Carbon::now()->format('Y-m-d H:i:s');
        $time = Carbon::now()->format('H:i:s');
        $kunjungan = DB::select('SELECT a.`tgl_masuk`FROM ts_kunjungan a WHERE a.kode_kunjungan = ?', [$kj]);
        $tgl_msk_skrining = Carbon::parse($kunjungan[0]->tgl_masuk)->subMinutes(10);
        $riwayatobat = DB::select('SELECT
        a.kode_layanan_header,
        a.id,
        a.kode_kunjungan,
        b.total_tarif,
        b.kode_barang,
        b.aturan_pakai,
        b.jumlah_layanan,
        c.nama_barang
         FROM
         ts_layanan_header a
         INNER JOIN ts_layanan_detail b ON b.row_id_header = a.id
         INNER JOIN mt_barang c ON c.kode_barang = b.kode_barang
         WHERE a.kode_layanan_header LIKE "%DP%"
         AND b.kode_tarif_detail NOT LIKE "%tx%"
         AND a.kode_kunjungan = ?', [$request->kj]);
        $riwayatrekonobat = DB::select('SELECT * FROM rekonsiliasi_obat
        WHERE kode_kunjungan = ?', [$kj]);
        $cek1 = DB::select('select * from ts_layanan_header where kode_kunjungan = ? and kode_unit = ?', [$kj, '3002']);
        $cek = DB::select('select *,date(tgl_baca) as tanggalnya,fc_acc_number_ris(id_detail) as acc_number from ts_hasil_expertisi where kode_kunjungan = ?', [$kj]);
        $cekpa = DB::select('SELECT
        kode_header
        , id_header
        , id_detail
        , unit_asal
        , no_rm
        , kode_kunjungan
        , fc_nama_px(no_rm) AS nama_px
        , hasil
        , fc_NAMA_PARAMEDIS1(kode_dokter) AS nama_dokter
        , tipe
        , diagnostik_klinik
        , diagnostik_pasca_bedah
        , tgl_baca
          FROM ts_hasil_expertisi_pa WHERE kode_kunjungan = ?', [$kj]);
        $riwayatorderrad = DB::select('SELECT
        a.no_rm,
        a.kode_layanan_header,
        b.id_layanan_detail,
        b.id as iddetail,
        a.id,
        b.total_tarif,
        fc_nama_tindakan(LEFT(b.kode_tarif_detail,6)) as nama_tindakan
        FROM
        ts_layanan_header_igd a
        INNER JOIN ts_layanan_detail_igd b ON b.row_id_header = a.id
        WHERE a.kode_unit = ?
        AND a.kode_kunjungan = ?
        AND a.status_order ="1"
        AND b.satus_order = "1"
        ', ['3003', $request->kj]);
        $riwayatorderlab = DB::select('SELECT
         a.no_rm,
         a.kode_layanan_header,
         b.id_layanan_detail,
         b.id as iddetail,
         a.id,
         b.total_tarif,
         fc_nama_tindakan(LEFT(b.kode_tarif_detail,6)) as nama_tindakan
         FROM
         ts_layanan_header_igd a
         INNER JOIN ts_layanan_detail_igd b ON b.row_id_header = a.id
         WHERE a.kode_unit = ?
         AND a.kode_kunjungan = ?
         AND a.status_order ="1"
         AND b.satus_order = "1"
         ', ['3002', $request->kj]);
        //  AND b.satus_order = "1"
        // $layananlab = DB::select("CALL SP_PANGGIL_TARIF_LAB('$kelas','')");
        $layananlab = DB::select("CALL SP_PANGGIL_TARIF_LAB('1','')");
        // $layanan = DB::select("CALL SP_CARI_TARIF_PELAYANAN_RAD('$ku','','$kelas')");

        $layanan = DB::select("CALL SP_CARI_TARIF_PELAYANAN_RAD('1','','1')");
        $diagnosa = DB::select('SELECT * FROM mt_jenis_diagnosa_medis');
        $alasanplg  = DB::select('SELECT * FROM mt_alasan_pulang');
        $ttv = DB::select('SELECT tekanan_darah, sumber_data, frekuensi_nafas, keadaan_umum, kesadaran, frekuensi_nadi, suhu, berat_badan, umur, GCS, SPO2 FROM erm_cppt_perawat WHERE no_rm = ? AND kode_kunjungan = ?', [$norm, $kj]);
        $assesdok = DB::select('SELECT * FROM erm_cppt_dokter WHERE no_rm = ? AND kode_kunjungan = ? AND status = 1', [$norm, $kj]);

        // $tindakan = DB::select('SELECT * FROM erm_tindakan_kedokteran WHERE no_rm = ? AND kode_kunjungan = ?', [$norm, $kj]);
        // $assesper = DB::select('SELECT * FROM erm_cppt_perawat
        //   WHERE no_rm = ? AND kode_kunjungan = ?', [$request->norm, $request->kj]);

        $assesper = DB::select('SELECT * FROM erm_cppt_perawat WHERE no_rm = ? AND kode_kunjungan = ? AND status IN (1,2)', [$norm, $kj]);

        $triase = DB::select('SELECT * FROM ts_triase
           WHERE no_rm = ? AND kode_kunjungan = ? AND STATUS IN (1) ', [$norm, $kj]);
        //    dd($triase);
        $dpjp = DB::select('SELECT 
                    a.kode_paramedis,
                    a.nama_paramedis
                    FROM mt_paramedis a
                    WHERE a.spesialis LIKE "%spesialis%"
                    AND a.act = 1');
        $riwayattindakandpjp = DB::select('SELECT id,fc_NAMA_PARAMEDIS1(a.kode_paramedis) AS nama_dpjp,a.kode_paramedis,a.tindakan_kedokteran FROM erm_tindakan_kedokteran a WHERE kode_kunjungan = ? AND status = 1', [$kj]);
        // dd($riwayattindakandpjp);
        $tindakanigd = DB::select("CALL SP_PANGGIL_TARIF_TINDAKAN_RS_2024_IGD('1','','')");
        $riwayatordergp = DB::select('SELECT
        a.no_rm,
        a.kode_layanan_header,
        b.id_layanan_detail,
        b.id as iddetail,
        a.id,
        fc_NAMA_PARAMEDIS1(b.kode_dokter1) AS nama_dokter,
        b.total_tarif,
        fc_nama_tindakan(LEFT(b.kode_tarif_detail,6)) as nama_tindakan
        FROM
        ts_layanan_header_igd a
        INNER JOIN ts_layanan_detail_igd b ON b.row_id_header = a.id
        WHERE a.kode_unit = ?
        AND a.kode_kunjungan = ?
        AND a.status_order ="1"
        AND b.satus_order = "1"', ['1002', $request->kj]);
        $ruang = DB::select('SELECT kode_unit,nama_unit FROM mt_unit WHERE kode_unit  LIKE "%20%" AND act = 1');

        return view(
            'dokter.formermdokter',
            [
                'title' => 'SiRAMAH DOKTER',
                'layananlab' => $layananlab,
                'riwayattindakandpjp' => $riwayattindakandpjp,
                'kunjungan' => $kunjungan,
