        WHERE id = ?', ['3', 'RETUR', $idrdetail]);

        $hitung = DB::select('SELECT total_tarif AS tarif FROM ts_layanan_detail_igd WHERE id_layanan_detail = ? AND kode_layanan_header = ? ', [$rdetail, $rheader]);
