            $sisatagpri = $tagpri - $tarrif;
            $updatehed = DB::select('UPDATE ts_layanan_header_igd	SET total_layanan = ? ,tagihan_pribadi = ?	WHERE kode_layanan_header = ?', [$sisatagpri,  $sisatagpri, $rheader]);
        }

        $back = [
