        if ($jenispasien == 'Pasien Anak') {
            $jenispasien = '1';
        } elseif ($jenispasien == 'Pasien Bedah') {
            $jenispasien = '2';
        } elseif ($jenispasien == 'Pasien Non Bedah') {
            $jenispasien = '3';
        } elseif ($jenispasien == 'Pasien Psikomatic') {
            $jenispasien = '4';
        } elseif ($jenispasien == 'Pasien Kebidanan') {
            $jenispasien = '5';
        } else {
            $jenispasien = '0';
        }

